modes.detail:
// ============ 为什么要两种表示都留着 ============
//
//   Prim 要频繁地问"哪个顶点离树最近" —— 用**邻接矩阵**方便。
//   Kruskal 要把边排序、还要判环     —— 用**边表**方便。
//
// 所以这一节两种都定义。这不是凑数，而是算法本身决定的数据结构选择：
// **先想清楚算法要反复做什么，再决定用什么存。**
//
// ============ 边表长什么样 ============
//
//   每条边存三个整数：起点、终点、权值。
//
//     边表:  (0,1,6) (0,2,1) (0,3,5) (1,3,5) ...
//
// 从邻接矩阵到边表的转换要注意：**无向图每条边会被数两次**，
// 所以只收 u < v 的那些，避免重复。

// 最多顶点数
#define MAXV 100

// 最多边数
#define MAXE 1000

// 没有边
#define INF 65535

// 带权图（邻接矩阵）
typedef struct
{
// 顶点数
    int nv;
// 边数
    int ne;
// g[i][j] 是权值，INF 表示无边
    int g[MAXV][MAXV];
} MGraph;

// 一条边
typedef struct
{
// 起点
    int u;
// 终点
    int v;
// 权值
    int w;
} Edge;

// 用带权边表建图
void CreateGraph(MGraph *G, int nv, const int edges[][3], int edgeCount)
{
// 循环用
    int i, j;

// 记规模
    G->nv = nv;
    G->ne = edgeCount;

// 初始化矩阵
    for (i = 0; i < nv; i++)
    {
        for (j = 0; j < nv; j++)
        {
            G->g[i][j] = (i == j) ? 0 : INF;
        }
    }

// 填边
    for (i = 0; i < edgeCount; i++)
    {
        G->g[edges[i][0]][edges[i][1]] = edges[i][2];
        G->g[edges[i][1]][edges[i][0]] = edges[i][2];
    }
}

// 从邻接矩阵抽出边表（供 Kruskal 用）
// 只收 u < v 的，避免同一条边收两次。
int BuildEdgeList(MGraph *G, Edge edges[])
{
// 循环用
    int i, j;
// 计数
    int count = 0;

    for (i = 0; i < G->nv; i++)
    {
        for (j = i + 1; j < G->nv; j++)
        {
// 有边就收进来
            if (G->g[i][j] < INF)
            {
                edges[count].u = i;
                edges[count].v = j;
                edges[count].w = G->g[i][j];
                count++;
            }
        }
    }

// 返回边数
    return count;
}

// 把一条边打印成 "u-v(w)" 的形式
void PrintEdge(Edge e)
{
    printf("%d-%d(%d)", e.u, e.v, e.w);
}

