modes.detail:
// ============ Prim 和 Dijkstra 长得几乎一样 ============
//
// 把两个算法的更新那一行摆在一起看：
//
//   Dijkstra:  dist[w] = dist[v] + G->g[v][w];   ← 加上"从源点过来的距离"
//   Prim    :  dist[w] = G->g[v][w];            ← 只看"到树的一条边"
//
// 差别就在这：Dijkstra 关心的是**从源点出发的总路程**，
// Prim 关心的是**这条边本身有多长**。
//
// 原因也很清楚：
//
//   · 最短路要"累计" —— 走的路越长，到终点就越远
//   · 生成树只看"每条边多长" —— 树的总权值是所有边相加，
//     所以只关心"新加进来的这条边"，不需要把前面的距离带上
//
// ============ dist 在这里是什么意思 ============
//
// Dijkstra 里 dist[w] = 源点到 w 的距离。
// Prim 里 dist[w] = **w 到"当前的树"最近的一条边的权值**。
//
// 所以一开始，只有起点自己和它的直连邻居有值，其余都是 INF。
// 每加进来一个顶点 v，就用 v 的边去更新其他还没入树的顶点。
//
// ============ 走一遍 ============
//
// 从 0 出发，dist 初值 = [0, 6, 1, 5, INF, INF]
//
//   第 1 轮：挑 dist 最小的未入树顶点 → 2（dist=1），加进来，总权值 +1
//            用 2 更新：2-3 权 2 < 5 → dist[3] = 2
//
//   第 2 轮：挑 → 3（dist=2），加进来，总权值 +2 = 3
//            用 3 更新：3-4 权 6 → dist[4]=6；3-5 权 4 → dist[5]=4
//
//   第 3 轮：挑 → 5（dist=4），总权值 3+4 = 7
//
//   第 4 轮：挑 → 1（dist=5），总权值 12
//
//   第 5 轮：挑 → 4（dist=3），总权值 15
//
// 一共加了 5 个顶点（n-1 条边），总权值 15。

// 从顶点 s 出发做 Prim，返回最小生成树的总权值；不连通返回 -1
int Prim(MGraph *G, int s, int parent[])
{
// dist[w]：w 到当前生成树最近的一条边的权值
    int dist[MAXV];
// visited[w]：w 是否已经入树
    int visited[MAXV];
// 总权值
    int total = 0;
// 循环用
    int i, v, w;
// 当前最小的 dist
    int minDist;

// 初始化
    for (i = 0; i < G->nv; i++)
    {
// 一开始"树"里只有 s，所以 dist 就是 s 到各点的直连边
        dist[i] = G->g[s][i];
// 记下每个点是从树里哪个点连过来的
        parent[i] = s;
// 都还没入树
        visited[i] = 0;
    }

// 起点入树
    dist[s] = 0;
    visited[s] = 1;
    parent[s] = -1;

// 还要加 n-1 个顶点
    for (i = 1; i < G->nv; i++)
    {
// ① 在没入树的顶点里找 dist 最小的
        v = -1;
        minDist = INF;

        for (w = 0; w < G->nv; w++)
        {
            if (visited[w] == 0 && dist[w] < minDist)
            {
                minDist = dist[w];
                v = w;
            }
        }

// 找不到说明图不连通，没有生成树
        if (v < 0)
        {
            return -1;
        }

// ② 把它加进树
        visited[v] = 1;
// 这条边的权值计入总权值
        total += dist[v];

// ③ 用 v 去更新其他顶点到树的距离
        for (w = 0; w < G->nv; w++)
        {
// 没入树、且有边、且这条边比原来更短
// 注意这里直接就是 G->g[v][w]，不加上 dist[v] —— 这就是和 Dijkstra 的差别。
            if (visited[w] == 0 && G->g[v][w] < dist[w])
            {
                dist[w] = G->g[v][w];
                parent[w] = v;
            }
        }
    }

// 返回总权值
    return total;
}

// 打印生成树的每条边（根据 parent 数组）
void PrintTreeEdges(int parent[], int n)
{
// 循环用
    int i;

    for (i = 0; i < n; i++)
    {
// 起点没有父亲
        if (parent[i] < 0)
        {
            continue;
        }
// 打印一条边
        printf("  (%d, %d)\n", parent[i], i);
    }
}

