// ============ Kruskal 为什么需要并查集 ============
//
// Kruskal 的做法是"从小到大试每条边，能加就加"。
// 问题是怎么判断"这条边能不能加" —— 也就是**加了会不会成环**。
//
// 一条边 (u, v) 会成环，等价于：**u 和 v 已经连通了**。
// 而"判断两点是否连通"正是并查集的看家本领（见 03-06）。
//
// 所以 Kruskal = 边排序 + 并查集，两个老朋友拼在一起。
//
// ============ 这里用最简版的并查集 ============
//
// 03-06 讲的是完整的并查集（负数存大小、按大小合并、路径压缩）。
// 这里为了不把篇幅拉太长，用简化版：
//
//     parent[i] = -1  表示 i 是根
//     parent[i] >= 0 表示 i 的父亲
//
// 只保留路径压缩（贡献最大的那个优化），不做按大小合并。
// 对 Kruskal 来说够用了 —— 因为边的数量通常不会太大。

// 找 x 所在集合的根（带路径压缩）
// parent[i] < 0 表示 i 是根
int FindRoot(int parent[], int x)
{
// 自己是根
    if (parent[x] < 0)
    {
        return x;
    }
// 否则递归往上找，并把结果写回去（路径压缩）
    return parent[x] = FindRoot(parent, parent[x]);
}

// 把两个集合合并
// 参数必须是根的下标
void UnionSets(int parent[], int r1, int r2)
{
// 随便挂：让 r2 认 r1 当父亲
// 简化版不做按大小合并，够用。
    parent[r2] = r1;
}

// 初始化并查集
void InitSets(int parent[], int n)
{
// 循环用
    int i;

// 每个元素各自成组
    for (i = 0; i < n; i++)
    {
        parent[i] = -1;
    }
