// ============ 为什么用冒泡 ============
//
// Kruskal 的正确性不依赖排序算法好不好，随便什么排序都行。
// 这里用冒泡是为了**代码短、好读**，把注意力留给算法本身。
//
// 真做工程的话边数可能上万，那就该换成快排（下一章会讲）。
//
// 复杂度上，冒泡是 O(e²)，快排是 O(e log e)。e 大的时候差很多。
// 但 Kruskal 本身的瓶颈通常也不在这儿。

// 把边表按权值从小到大排序（冒泡）
void SortEdges(Edge edges[], int n)
{
// 循环用
    int i, j;
// 交换用
    Edge tmp;

    for (i = 0; i < n - 1; i++)
    {
        for (j = 0; j < n - 1 - i; j++)
        {
// 前面的比后面大就交换
            if (edges[j].w > edges[j + 1].w)
            {
                tmp = edges[j];
                edges[j] = edges[j + 1];
                edges[j + 1] = tmp;
            }
        }
    }
}

// 打印边表
void PrintEdges(Edge edges[], int n)
{
// 循环用
    int i;

    for (i = 0; i < n; i++)
    {
        printf("  ");
        PrintEdge(edges[i]);
        printf("\n");
    }
}

