modes.detail:
// ============ Kruskal 的三步 ============
//
//   ① 把所有边按权值从小到大排序
//   ② 依次看每条边：两端的顶点还不连通 → 加进来；已经连通 → 跳过（会成环）
//   ③ 加够 n-1 条就停
//
// 为什么加够 n-1 条就能停？因为 n 个顶点的树正好有 n-1 条边。
// 如果所有边试完还没到 n-1 条，说明图不连通。
//
// ============ 为什么先试短的边一定对 ============
//
// 这是贪心。直觉上：既然要"总权值最小"，那能用短边就用短边。
//
// 严格证明要用"割"的概念，但有个很实用的理解方式：
//
//   把边按从小到大排好之后，"最短的那条边"一定可以入选 ——
//   因为它不成环（图里只有它一条边时不可能成环），
//   而任何生成树都必须跨过它连接的那两个连通块，早晚要用一条边，
//   用最短的那条不会更差。
//
// 这就是 Kruskal 的核心：**每一步都在当前能选的里面挑最短的。**
//
// ============ Prim 和 Kruskal 的关系 ============
//
// 两者都是贪心，结果的总权值**一定相同**（虽然可能选出不同的边）。
//
//   看"点"贪心 → Prim，适合稠密图（O(n²)，不依赖边数）
//   看"边"贪心 → Kruskal，适合稀疏图（O(e log e)，只和边数有关）
//
// 所以稠密图用 Prim、稀疏图用 Kruskal —— 和邻接矩阵/邻接表的选择是一个道理。

// Kruskal：返回最小生成树总权值；不连通返回 -1
int Kruskal(MGraph *G, Edge edges[], int edgeCount)
{
// 并查集
    int parent[MAXV];
// 总权值
    int total = 0;
// 已经加了几条边
    int count = 0;
// 循环用
    int i;
// 边两端的根
    int ru, rv;

// 初始化并查集：每个顶点各自一组
    InitSets(parent, G->nv);

// ① 边按权值排序
    SortEdges(edges, edgeCount);

// ② 依次看每条边
// 循环条件里带 `count < G->nv - 1`，是为了"加够了就提前收工"。
    for (i = 0; i < edgeCount && count < G->nv - 1; i++)
    {
// 找两端的根
        ru = FindRoot(parent, edges[i].u);
        rv = FindRoot(parent, edges[i].v);

// 根相同 → 已经连通 → 这条边会成环，跳过
        if (ru == rv)
        {
            continue;
        }

// ③ 不成环 → 加进来
        UnionSets(parent, ru, rv);
        total += edges[i].w;
        count++;
    }

// 边数和 n-1 对不上说明图不连通
    if (count != G->nv - 1)
    {
        return -1;
    }

// 返回总权值
    return total;
}

