// ============ 为什么要两个都算一遍 ============
//
// 因为它们是两种完全不同的思路，**结果必须一样**。
//
// 如果总权值不同，那至少有一个是错的 —— 这种"两条路互相验证"
// 比只看一个结果可靠得多，前面最大子列和那节也用过这一招。

// 主函数
int main(void)
{
// 带权边表：{ 起点, 终点, 权值 }
// 6 个顶点的一张带权图。
    static const int edges[][3] = {
        { 0, 1, 6 }, { 0, 2, 1 }, { 0, 3, 5 },
        { 1, 3, 5 }, { 1, 4, 3 },
        { 2, 3, 2 },
        { 3, 4, 6 }, { 3, 5, 4 },
        { 4, 5, 6 }
    };
// 边数
    int edgeCount = 9;
// 图
    MGraph G;
// 生成树里每个点的父亲
    int parent[MAXV];
// 边表
    Edge edgeList[MAXE];
// 两个算法的结果
    int primTotal, kruskalTotal;
// 实际抽出的边数
    int n;
// 循环用
    int i;

// 建图
    CreateGraph(&G, 6, edges, edgeCount);

// 打印邻接矩阵
    printf("带权图的邻接矩阵（INF = 无边）：\n");
    printf("      ");
    for (i = 0; i < G.nv; i++)
    {
        printf("%5d", i);
    }
    printf("\n");

    for (i = 0; i < G.nv; i++)
    {
        printf("  %2d [", i);
        for (int j = 0; j < G.nv; j++)
        {
            if (G.g[i][j] >= INF)
            {
                printf("%5s", "INF");
            }
            else
            {
                printf("%5d", G.g[i][j]);
            }
        }
        printf(" ]\n");
    }
    printf("\n");

// 抽边表
    n = BuildEdgeList(&G, edgeList);
    printf("按邻接矩阵抽出来的边表（%d 条，只收 u<v 的避免重复）：\n", n);
    PrintEdges(edgeList, n);

// ==== Prim ====
    printf("\n=== Prim（加点法）===\n");
    primTotal = Prim(&G, 0, parent);

    if (primTotal < 0)
    {
        printf("  图不连通，没有生成树\n");
    }
    else
    {
        printf("  选出的边：\n");
        PrintTreeEdges(parent, G.nv);
        printf("  总权值 = %d\n", primTotal);
    }

// 重新抽一次边表（上一个算法的排序会打乱它，为了对比干净）
    n = BuildEdgeList(&G, edgeList);

// ==== Kruskal ====
    printf("\n=== Kruskal（加边法）===\n");
    kruskalTotal = Kruskal(&G, edgeList, n);

    if (kruskalTotal < 0)
    {
        printf("  图不连通，没有生成树\n");
    }
    else
    {
        printf("  总权值 = %d\n", kruskalTotal);
    }

// 两个结果必须一致
    printf("\n两种算法结果对比：\n");
    printf("  Prim    = %d\n", primTotal);
    printf("  Kruskal = %d\n", kruskalTotal);

    if (primTotal == kruskalTotal)
    {
        printf("  一致 —— 两种完全不同的思路给出同一个总权值，说明都对\n");
    }
    else
    {
        printf("  不一致！至少有一个写错了\n");
    }

    printf("\n（Prim 和 Dijkstra 只差一行：\n");
    printf("  Dijkstra 是 dist[v] + g[v][w]，Prim 是 g[v][w]）\n");

// 正常结束
    return 0;
}

