#include <stdio.h>
#include <stdlib.h>

/* ======== [已给出] 模块 01 typedef ======== */

#define MAXV 100

#define MAXE 1000

#define INF 65535

typedef struct
{
    int nv;
    int ne;
    int g[MAXV][MAXV];
} MGraph;

typedef struct
{
    int u;
    int v;
    int w;
} Edge;

void CreateGraph(MGraph *G, int nv, const int edges[][3], int edgeCount)
{
    int i, j;

    G->nv = nv;
    G->ne = edgeCount;

    for (i = 0; i < nv; i++)
    {
        for (j = 0; j < nv; j++)
        {
            G->g[i][j] = (i == j) ? 0 : INF;
        }
    }

    for (i = 0; i < edgeCount; i++)
    {
        G->g[edges[i][0]][edges[i][1]] = edges[i][2];
        G->g[edges[i][1]][edges[i][0]] = edges[i][2];
    }
}

int BuildEdgeList(MGraph *G, Edge edges[])
{
    int i, j;
    int count = 0;

    for (i = 0; i < G->nv; i++)
    {
        for (j = i + 1; j < G->nv; j++)
        {
            if (G->g[i][j] < INF)
            {
                edges[count].u = i;
                edges[count].v = j;
                edges[count].w = G->g[i][j];
                count++;
            }
        }
    }

    return count;
}

void PrintEdge(Edge e)
{
    printf("%d-%d(%d)", e.u, e.v, e.w);
}

/* ======== [已给出] 模块 02 Prim ======== */

int Prim(MGraph *G, int s, int parent[])
{
    int dist[MAXV];
    int visited[MAXV];
    int total = 0;
    int i, v, w;
    int minDist;

    for (i = 0; i < G->nv; i++)
    {
        dist[i] = G->g[s][i];
        parent[i] = s;
        visited[i] = 0;
    }

    dist[s] = 0;
    visited[s] = 1;
    parent[s] = -1;

    for (i = 1; i < G->nv; i++)
    {
        v = -1;
        minDist = INF;

        for (w = 0; w < G->nv; w++)
        {
            if (visited[w] == 0 && dist[w] < minDist)
            {
                minDist = dist[w];
                v = w;
            }
        }

        if (v < 0)
        {
            return -1;
        }

        visited[v] = 1;
        total += dist[v];

        for (w = 0; w < G->nv; w++)
        {
            if (visited[w] == 0 && G->g[v][w] < dist[w])
            {
                dist[w] = G->g[v][w];
                parent[w] = v;
            }
        }
    }

    return total;
}

void PrintTreeEdges(int parent[], int n)
{
    int i;

    for (i = 0; i < n; i++)
    {
        if (parent[i] < 0)
        {
            continue;
        }
        printf("  (%d, %d)\n", parent[i], i);
    }
}

/* ======== [已给出] 模块 03 FindRoot ======== */

int FindRoot(int parent[], int x)
{
    if (parent[x] < 0)
    {
        return x;
    }
    return parent[x] = FindRoot(parent, parent[x]);
}

void UnionSets(int parent[], int r1, int r2)
{
    parent[r2] = r1;
}

void InitSets(int parent[], int n)
{
    int i;

    for (i = 0; i < n; i++)
    {
        parent[i] = -1;
    }
}

/* ======== [已给出] 模块 04 SortEdges ======== */

void SortEdges(Edge edges[], int n)
{
    int i, j;
    Edge tmp;

    for (i = 0; i < n - 1; i++)
    {
        for (j = 0; j < n - 1 - i; j++)
        {
            if (edges[j].w > edges[j + 1].w)
            {
                tmp = edges[j];
                edges[j] = edges[j + 1];
                edges[j + 1] = tmp;
            }
        }
    }
}

void PrintEdges(Edge edges[], int n)
{
    int i;

    for (i = 0; i < n; i++)
    {
        printf("  ");
        PrintEdge(edges[i]);
        printf("\n");
    }
}

/* ======== [已给出] 模块 05 Kruskal ======== */

int Kruskal(MGraph *G, Edge edges[], int edgeCount)
{
    int parent[MAXV];
    int total = 0;
    int count = 0;
    int i;
    int ru, rv;

    InitSets(parent, G->nv);

    SortEdges(edges, edgeCount);

    for (i = 0; i < edgeCount && count < G->nv - 1; i++)
    {
        ru = FindRoot(parent, edges[i].u);
        rv = FindRoot(parent, edges[i].v);

        if (ru == rv)
        {
            continue;
        }

        UnionSets(parent, ru, rv);
        total += edges[i].w;
        count++;
    }

    if (count != G->nv - 1)
    {
        return -1;
    }

    return total;
}

/* ====================================================================
 *  轮到你了：模块 06  main
 *  作用：同一张图，Prim 和 Kruskal 应该给出同一个总权值。
 *  提示：先写函数签名，再写循环定位，最后写指针操作。
 *  写完按 Ctrl + Enter 编译运行，点"对比"看与参考实现的差异。
 * ==================================================================== */

modes.detail:
#include <stdio.h>
#include <stdlib.h>

// ============ 为什么要两种表示都留着 ============
//
//   Prim 要频繁地问"哪个顶点离树最近" —— 用**邻接矩阵**方便。
//   Kruskal 要把边排序、还要判环     —— 用**边表**方便。
//
// 所以这一节两种都定义。这不是凑数，而是算法本身决定的数据结构选择：
// **先想清楚算法要反复做什么，再决定用什么存。**
//
// ============ 边表长什么样 ============
//
//   每条边存三个整数：起点、终点、权值。
//
//     边表:  (0,1,6) (0,2,1) (0,3,5) (1,3,5) ...
//
// 从邻接矩阵到边表的转换要注意：**无向图每条边会被数两次**，
// 所以只收 u < v 的那些，避免重复。

// 最多顶点数
#define MAXV 100

// 最多边数
#define MAXE 1000

// 没有边
#define INF 65535

// 带权图（邻接矩阵）
typedef struct
{
// 顶点数
    int nv;
// 边数
    int ne;
// g[i][j] 是权值，INF 表示无边
    int g[MAXV][MAXV];
} MGraph;

// 一条边
typedef struct
{
// 起点
    int u;
// 终点
    int v;
// 权值
    int w;
} Edge;

// 用带权边表建图
void CreateGraph(MGraph *G, int nv, const int edges[][3], int edgeCount)
{
// 循环用
    int i, j;

// 记规模
    G->nv = nv;
    G->ne = edgeCount;

// 初始化矩阵
    for (i = 0; i < nv; i++)
    {
        for (j = 0; j < nv; j++)
        {
            G->g[i][j] = (i == j) ? 0 : INF;
        }
    }

// 填边
    for (i = 0; i < edgeCount; i++)
    {
        G->g[edges[i][0]][edges[i][1]] = edges[i][2];
        G->g[edges[i][1]][edges[i][0]] = edges[i][2];
    }
}

// 从邻接矩阵抽出边表（供 Kruskal 用）
// 只收 u < v 的，避免同一条边收两次。
int BuildEdgeList(MGraph *G, Edge edges[])
{
// 循环用
    int i, j;
// 计数
    int count = 0;

    for (i = 0; i < G->nv; i++)
    {
        for (j = i + 1; j < G->nv; j++)
        {
// 有边就收进来
            if (G->g[i][j] < INF)
            {
                edges[count].u = i;
                edges[count].v = j;
                edges[count].w = G->g[i][j];
                count++;
            }
        }
    }

// 返回边数
    return count;
}

// 把一条边打印成 "u-v(w)" 的形式
void PrintEdge(Edge e)
{
    printf("%d-%d(%d)", e.u, e.v, e.w);
}

// ============ Prim 和 Dijkstra 长得几乎一样 ============
//
// 把两个算法的更新那一行摆在一起看：
//
//   Dijkstra:  dist[w] = dist[v] + G->g[v][w];   ← 加上"从源点过来的距离"
//   Prim    :  dist[w] = G->g[v][w];            ← 只看"到树的一条边"
//
// 差别就在这：Dijkstra 关心的是**从源点出发的总路程**，
// Prim 关心的是**这条边本身有多长**。
//
// 原因也很清楚：
//
//   · 最短路要"累计" —— 走的路越长，到终点就越远
//   · 生成树只看"每条边多长" —— 树的总权值是所有边相加，
//     所以只关心"新加进来的这条边"，不需要把前面的距离带上
//
// ============ dist 在这里是什么意思 ============
//
// Dijkstra 里 dist[w] = 源点到 w 的距离。
// Prim 里 dist[w] = **w 到"当前的树"最近的一条边的权值**。
//
// 所以一开始，只有起点自己和它的直连邻居有值，其余都是 INF。
// 每加进来一个顶点 v，就用 v 的边去更新其他还没入树的顶点。
//
// ============ 走一遍 ============
//
// 从 0 出发，dist 初值 = [0, 6, 1, 5, INF, INF]
//
//   第 1 轮：挑 dist 最小的未入树顶点 → 2（dist=1），加进来，总权值 +1
//            用 2 更新：2-3 权 2 < 5 → dist[3] = 2
//
//   第 2 轮：挑 → 3（dist=2），加进来，总权值 +2 = 3
//            用 3 更新：3-4 权 6 → dist[4]=6；3-5 权 4 → dist[5]=4
//
//   第 3 轮：挑 → 5（dist=4），总权值 3+4 = 7
//
//   第 4 轮：挑 → 1（dist=5），总权值 12
//
//   第 5 轮：挑 → 4（dist=3），总权值 15
//
// 一共加了 5 个顶点（n-1 条边），总权值 15。

// 从顶点 s 出发做 Prim，返回最小生成树的总权值；不连通返回 -1
int Prim(MGraph *G, int s, int parent[])
{
// dist[w]：w 到当前生成树最近的一条边的权值
    int dist[MAXV];
// visited[w]：w 是否已经入树
    int visited[MAXV];
// 总权值
    int total = 0;
// 循环用
    int i, v, w;
// 当前最小的 dist
    int minDist;

// 初始化
    for (i = 0; i < G->nv; i++)
    {
// 一开始"树"里只有 s，所以 dist 就是 s 到各点的直连边
        dist[i] = G->g[s][i];
// 记下每个点是从树里哪个点连过来的
        parent[i] = s;
// 都还没入树
        visited[i] = 0;
    }

// 起点入树
    dist[s] = 0;
    visited[s] = 1;
    parent[s] = -1;

// 还要加 n-1 个顶点
    for (i = 1; i < G->nv; i++)
    {
// ① 在没入树的顶点里找 dist 最小的
        v = -1;
        minDist = INF;

        for (w = 0; w < G->nv; w++)
        {
            if (visited[w] == 0 && dist[w] < minDist)
            {
                minDist = dist[w];
                v = w;
            }
        }

// 找不到说明图不连通，没有生成树
        if (v < 0)
        {
            return -1;
        }

// ② 把它加进树
        visited[v] = 1;
// 这条边的权值计入总权值
        total += dist[v];

// ③ 用 v 去更新其他顶点到树的距离
        for (w = 0; w < G->nv; w++)
        {
// 没入树、且有边、且这条边比原来更短
// 注意这里直接就是 G->g[v][w]，不加上 dist[v] —— 这就是和 Dijkstra 的差别。
            if (visited[w] == 0 && G->g[v][w] < dist[w])
            {
                dist[w] = G->g[v][w];
                parent[w] = v;
            }
        }
    }

// 返回总权值
    return total;
}

// 打印生成树的每条边（根据 parent 数组）
void PrintTreeEdges(int parent[], int n)
{
// 循环用
    int i;

    for (i = 0; i < n; i++)
    {
// 起点没有父亲
        if (parent[i] < 0)
        {
            continue;
        }
// 打印一条边
        printf("  (%d, %d)\n", parent[i], i);
    }
}

// ============ Kruskal 为什么需要并查集 ============
//
// Kruskal 的做法是"从小到大试每条边，能加就加"。
// 问题是怎么判断"这条边能不能加" —— 也就是**加了会不会成环**。
//
// 一条边 (u, v) 会成环，等价于：**u 和 v 已经连通了**。
// 而"判断两点是否连通"正是并查集的看家本领（见 03-06）。
//
// 所以 Kruskal = 边排序 + 并查集，两个老朋友拼在一起。
//
// ============ 这里用最简版的并查集 ============
//
// 03-06 讲的是完整的并查集（负数存大小、按大小合并、路径压缩）。
// 这里为了不把篇幅拉太长，用简化版：
//
//     parent[i] = -1  表示 i 是根
//     parent[i] >= 0 表示 i 的父亲
//
// 只保留路径压缩（贡献最大的那个优化），不做按大小合并。
// 对 Kruskal 来说够用了 —— 因为边的数量通常不会太大。

// 找 x 所在集合的根（带路径压缩）
// parent[i] < 0 表示 i 是根
int FindRoot(int parent[], int x)
{
// 自己是根
    if (parent[x] < 0)
    {
        return x;
    }
// 否则递归往上找，并把结果写回去（路径压缩）
    return parent[x] = FindRoot(parent, parent[x]);
}

// 把两个集合合并
// 参数必须是根的下标
void UnionSets(int parent[], int r1, int r2)
{
// 随便挂：让 r2 认 r1 当父亲
// 简化版不做按大小合并，够用。
    parent[r2] = r1;
}

// 初始化并查集
void InitSets(int parent[], int n)
{
// 循环用
    int i;

// 每个元素各自成组
    for (i = 0; i < n; i++)
    {
        parent[i] = -1;
    }
}

// ============ 为什么用冒泡 ============
//
// Kruskal 的正确性不依赖排序算法好不好，随便什么排序都行。
// 这里用冒泡是为了**代码短、好读**，把注意力留给算法本身。
//
// 真做工程的话边数可能上万，那就该换成快排（下一章会讲）。
//
// 复杂度上，冒泡是 O(e²)，快排是 O(e log e)。e 大的时候差很多。
// 但 Kruskal 本身的瓶颈通常也不在这儿。

// 把边表按权值从小到大排序（冒泡）
void SortEdges(Edge edges[], int n)
{
// 循环用
    int i, j;
// 交换用
    Edge tmp;

    for (i = 0; i < n - 1; i++)
    {
        for (j = 0; j < n - 1 - i; j++)
        {
// 前面的比后面大就交换
            if (edges[j].w > edges[j + 1].w)
            {
                tmp = edges[j];
                edges[j] = edges[j + 1];
                edges[j + 1] = tmp;
            }
        }
    }
}

// 打印边表
void PrintEdges(Edge edges[], int n)
{
// 循环用
    int i;

    for (i = 0; i < n; i++)
    {
        printf("  ");
        PrintEdge(edges[i]);
        printf("\n");
    }
}

// ============ Kruskal 的三步 ============
//
//   ① 把所有边按权值从小到大排序
//   ② 依次看每条边：两端的顶点还不连通 → 加进来；已经连通 → 跳过（会成环）
//   ③ 加够 n-1 条就停
//
// 为什么加够 n-1 条就能停？因为 n 个顶点的树正好有 n-1 条边。
// 如果所有边试完还没到 n-1 条，说明图不连通。
//
// ============ 为什么先试短的边一定对 ============
//
// 这是贪心。直觉上：既然要"总权值最小"，那能用短边就用短边。
//
// 严格证明要用"割"的概念，但有个很实用的理解方式：
//
//   把边按从小到大排好之后，"最短的那条边"一定可以入选 ——
//   因为它不成环（图里只有它一条边时不可能成环），
//   而任何生成树都必须跨过它连接的那两个连通块，早晚要用一条边，
//   用最短的那条不会更差。
//
// 这就是 Kruskal 的核心：**每一步都在当前能选的里面挑最短的。**
//
// ============ Prim 和 Kruskal 的关系 ============
//
// 两者都是贪心，结果的总权值**一定相同**（虽然可能选出不同的边）。
//
//   看"点"贪心 → Prim，适合稠密图（O(n²)，不依赖边数）
//   看"边"贪心 → Kruskal，适合稀疏图（O(e log e)，只和边数有关）
//
// 所以稠密图用 Prim、稀疏图用 Kruskal —— 和邻接矩阵/邻接表的选择是一个道理。

// Kruskal：返回最小生成树总权值；不连通返回 -1
int Kruskal(MGraph *G, Edge edges[], int edgeCount)
{
// 并查集
    int parent[MAXV];
// 总权值
    int total = 0;
// 已经加了几条边
    int count = 0;
// 循环用
    int i;
// 边两端的根
    int ru, rv;

// 初始化并查集：每个顶点各自一组
    InitSets(parent, G->nv);

// ① 边按权值排序
    SortEdges(edges, edgeCount);

// ② 依次看每条边
// 循环条件里带 `count < G->nv - 1`，是为了"加够了就提前收工"。
    for (i = 0; i < edgeCount && count < G->nv - 1; i++)
    {
// 找两端的根
        ru = FindRoot(parent, edges[i].u);
        rv = FindRoot(parent, edges[i].v);

// 根相同 → 已经连通 → 这条边会成环，跳过
        if (ru == rv)
        {
            continue;
        }

// ③ 不成环 → 加进来
        UnionSets(parent, ru, rv);
        total += edges[i].w;
        count++;
    }

// 边数和 n-1 对不上说明图不连通
    if (count != G->nv - 1)
    {
        return -1;
    }

// 返回总权值
    return total;
}

// ============ 为什么要两个都算一遍 ============
//
// 因为它们是两种完全不同的思路，**结果必须一样**。
//
// 如果总权值不同，那至少有一个是错的 —— 这种"两条路互相验证"
// 比只看一个结果可靠得多，前面最大子列和那节也用过这一招。

// 主函数
int main(void)
{
// 带权边表：{ 起点, 终点, 权值 }
// 6 个顶点的一张带权图。
    static const int edges[][3] = {
        { 0, 1, 6 }, { 0, 2, 1 }, { 0, 3, 5 },
        { 1, 3, 5 }, { 1, 4, 3 },
        { 2, 3, 2 },
        { 3, 4, 6 }, { 3, 5, 4 },
        { 4, 5, 6 }
    };
// 边数
    int edgeCount = 9;
// 图
    MGraph G;
// 生成树里每个点的父亲
    int parent[MAXV];
// 边表
    Edge edgeList[MAXE];
// 两个算法的结果
    int primTotal, kruskalTotal;
// 实际抽出的边数
    int n;
// 循环用
    int i;

// 建图
    CreateGraph(&G, 6, edges, edgeCount);

// 打印邻接矩阵
    printf("带权图的邻接矩阵（INF = 无边）：\n");
    printf("      ");
    for (i = 0; i < G.nv; i++)
    {
        printf("%5d", i);
    }
    printf("\n");

    for (i = 0; i < G.nv; i++)
    {
        printf("  %2d [", i);
        for (int j = 0; j < G.nv; j++)
        {
            if (G.g[i][j] >= INF)
            {
                printf("%5s", "INF");
            }
            else
            {
                printf("%5d", G.g[i][j]);
            }
        }
        printf(" ]\n");
    }
    printf("\n");

// 抽边表
    n = BuildEdgeList(&G, edgeList);
    printf("按邻接矩阵抽出来的边表（%d 条，只收 u<v 的避免重复）：\n", n);
    PrintEdges(edgeList, n);

// ==== Prim ====
    printf("\n=== Prim（加点法）===\n");
    primTotal = Prim(&G, 0, parent);

    if (primTotal < 0)
    {
        printf("  图不连通，没有生成树\n");
    }
    else
    {
        printf("  选出的边：\n");
        PrintTreeEdges(parent, G.nv);
        printf("  总权值 = %d\n", primTotal);
    }

// 重新抽一次边表（上一个算法的排序会打乱它，为了对比干净）
    n = BuildEdgeList(&G, edgeList);

// ==== Kruskal ====
    printf("\n=== Kruskal（加边法）===\n");
    kruskalTotal = Kruskal(&G, edgeList, n);

    if (kruskalTotal < 0)
    {
        printf("  图不连通，没有生成树\n");
    }
    else
    {
        printf("  总权值 = %d\n", kruskalTotal);
    }

// 两个结果必须一致
    printf("\n两种算法结果对比：\n");
    printf("  Prim    = %d\n", primTotal);
    printf("  Kruskal = %d\n", kruskalTotal);

    if (primTotal == kruskalTotal)
    {
        printf("  一致 —— 两种完全不同的思路给出同一个总权值，说明都对\n");
    }
    else
    {
        printf("  不一致！至少有一个写错了\n");
    }

    printf("\n（Prim 和 Dijkstra 只差一行：\n");
    printf("  Dijkstra 是 dist[v] + g[v][w]，Prim 是 g[v][w]）\n");

// 正常结束
    return 0;
}

modes.short:
#include <stdio.h>
#include <stdlib.h>


// 最多顶点数
#define MAXV 100

// 最多边数
#define MAXE 1000

// 没有边
#define INF 65535

// 带权图（邻接矩阵）
typedef struct
{
// 顶点数
    int nv;
// 边数
    int ne;
// g[i][j] 是权值，INF 表示无边
    int g[MAXV][MAXV];
} MGraph;

// 一条边
typedef struct
{
// 起点
    int u;
// 终点
    int v;
// 权值
    int w;
} Edge;

// 用带权边表建图
void CreateGraph(MGraph *G, int nv, const int edges[][3], int edgeCount)
{
// 循环用
    int i, j;

// 记规模
    G->nv = nv;
    G->ne = edgeCount;

// 初始化矩阵
    for (i = 0; i < nv; i++)
    {
        for (j = 0; j < nv; j++)
        {
            G->g[i][j] = (i == j) ? 0 : INF;
        }
    }

// 填边
    for (i = 0; i < edgeCount; i++)
    {
        G->g[edges[i][0]][edges[i][1]] = edges[i][2];
        G->g[edges[i][1]][edges[i][0]] = edges[i][2];
    }
}

// 从邻接矩阵抽出边表（供 Kruskal 用）
int BuildEdgeList(MGraph *G, Edge edges[])
{
// 循环用
    int i, j;
// 计数
    int count = 0;

    for (i = 0; i < G->nv; i++)
    {
        for (j = i + 1; j < G->nv; j++)
        {
// 有边就收进来
            if (G->g[i][j] < INF)
            {
                edges[count].u = i;
                edges[count].v = j;
                edges[count].w = G->g[i][j];
                count++;
            }
        }
    }

// 返回边数
    return count;
}

// 把一条边打印成 "u-v(w)" 的形式
void PrintEdge(Edge e)
{
    printf("%d-%d(%d)", e.u, e.v, e.w);
}


// 从顶点 s 出发做 Prim，返回最小生成树的总权值；不连通返回 -1
int Prim(MGraph *G, int s, int parent[])
{
// dist[w]：w 到当前生成树最近的一条边的权值
    int dist[MAXV];
// visited[w]：w 是否已经入树
    int visited[MAXV];
// 总权值
    int total = 0;
// 循环用
    int i, v, w;
// 当前最小的 dist
    int minDist;

// 初始化
    for (i = 0; i < G->nv; i++)
    {
// 一开始"树"里只有 s，所以 dist 就是 s 到各点的直连边
        dist[i] = G->g[s][i];
// 记下每个点是从树里哪个点连过来的
        parent[i] = s;
// 都还没入树
        visited[i] = 0;
    }

// 起点入树
    dist[s] = 0;
    visited[s] = 1;
    parent[s] = -1;

// 还要加 n-1 个顶点
    for (i = 1; i < G->nv; i++)
    {
// ① 在没入树的顶点里找 dist 最小的
        v = -1;
        minDist = INF;

        for (w = 0; w < G->nv; w++)
        {
            if (visited[w] == 0 && dist[w] < minDist)
            {
                minDist = dist[w];
                v = w;
            }
        }

// 找不到说明图不连通，没有生成树
        if (v < 0)
        {
            return -1;
        }

// ② 把它加进树
        visited[v] = 1;
// 这条边的权值计入总权值
        total += dist[v];

// ③ 用 v 去更新其他顶点到树的距离
        for (w = 0; w < G->nv; w++)
        {
// 没入树、且有边、且这条边比原来更短
            if (visited[w] == 0 && G->g[v][w] < dist[w])
            {
                dist[w] = G->g[v][w];
                parent[w] = v;
            }
        }
    }

// 返回总权值
    return total;
}

// 打印生成树的每条边（根据 parent 数组）
void PrintTreeEdges(int parent[], int n)
{
// 循环用
    int i;

    for (i = 0; i < n; i++)
    {
// 起点没有父亲
        if (parent[i] < 0)
        {
            continue;
        }
// 打印一条边
        printf("  (%d, %d)\n", parent[i], i);
    }
}


// 找 x 所在集合的根（带路径压缩）
int FindRoot(int parent[], int x)
{
// 自己是根
    if (parent[x] < 0)
    {
        return x;
    }
// 否则递归往上找，并把结果写回去（路径压缩）
    return parent[x] = FindRoot(parent, parent[x]);
}

// 把两个集合合并
void UnionSets(int parent[], int r1, int r2)
{
// 随便挂：让 r2 认 r1 当父亲
    parent[r2] = r1;
}

// 初始化并查集
void InitSets(int parent[], int n)
{
// 循环用
    int i;

// 每个元素各自成组
    for (i = 0; i < n; i++)
    {
        parent[i] = -1;
    }
}


// 把边表按权值从小到大排序（冒泡）
void SortEdges(Edge edges[], int n)
{
// 循环用
    int i, j;
// 交换用
    Edge tmp;

    for (i = 0; i < n - 1; i++)
    {
        for (j = 0; j < n - 1 - i; j++)
        {
// 前面的比后面大就交换
            if (edges[j].w > edges[j + 1].w)
            {
                tmp = edges[j];
                edges[j] = edges[j + 1];
                edges[j + 1] = tmp;
            }
        }
    }
}

// 打印边表
void PrintEdges(Edge edges[], int n)
{
// 循环用
    int i;

    for (i = 0; i < n; i++)
    {
        printf("  ");
        PrintEdge(edges[i]);
        printf("\n");
    }
}


// Kruskal：返回最小生成树总权值；不连通返回 -1
int Kruskal(MGraph *G, Edge edges[], int edgeCount)
{
// 并查集
    int parent[MAXV];
// 总权值
    int total = 0;
// 已经加了几条边
    int count = 0;
// 循环用
    int i;
// 边两端的根
    int ru, rv;

// 初始化并查集：每个顶点各自一组
    InitSets(parent, G->nv);

// ① 边按权值排序
    SortEdges(edges, edgeCount);

// ② 依次看每条边
    for (i = 0; i < edgeCount && count < G->nv - 1; i++)
    {
// 找两端的根
        ru = FindRoot(parent, edges[i].u);
        rv = FindRoot(parent, edges[i].v);

// 根相同 → 已经连通 → 这条边会成环，跳过
        if (ru == rv)
        {
            continue;
        }

// ③ 不成环 → 加进来
        UnionSets(parent, ru, rv);
        total += edges[i].w;
        count++;
    }

// 边数和 n-1 对不上说明图不连通
    if (count != G->nv - 1)
    {
        return -1;
    }

// 返回总权值
    return total;
}


// 主函数
int main(void)
{
// 带权边表：{ 起点, 终点, 权值 }
    static const int edges[][3] = {
        { 0, 1, 6 }, { 0, 2, 1 }, { 0, 3, 5 },
        { 1, 3, 5 }, { 1, 4, 3 },
        { 2, 3, 2 },
        { 3, 4, 6 }, { 3, 5, 4 },
        { 4, 5, 6 }
    };
// 边数
    int edgeCount = 9;
// 图
    MGraph G;
// 生成树里每个点的父亲
    int parent[MAXV];
// 边表
    Edge edgeList[MAXE];
// 两个算法的结果
    int primTotal, kruskalTotal;
// 实际抽出的边数
    int n;
// 循环用
    int i;

// 建图
    CreateGraph(&G, 6, edges, edgeCount);

// 打印邻接矩阵
    printf("带权图的邻接矩阵（INF = 无边）：\n");
    printf("      ");
    for (i = 0; i < G.nv; i++)
    {
        printf("%5d", i);
    }
    printf("\n");

    for (i = 0; i < G.nv; i++)
    {
        printf("  %2d [", i);
        for (int j = 0; j < G.nv; j++)
        {
            if (G.g[i][j] >= INF)
            {
                printf("%5s", "INF");
            }
            else
            {
                printf("%5d", G.g[i][j]);
            }
        }
        printf(" ]\n");
    }
    printf("\n");

// 抽边表
    n = BuildEdgeList(&G, edgeList);
    printf("按邻接矩阵抽出来的边表（%d 条，只收 u<v 的避免重复）：\n", n);
    PrintEdges(edgeList, n);

// ==== Prim ====
    printf("\n=== Prim（加点法）===\n");
    primTotal = Prim(&G, 0, parent);

    if (primTotal < 0)
    {
        printf("  图不连通，没有生成树\n");
    }
    else
    {
        printf("  选出的边：\n");
        PrintTreeEdges(parent, G.nv);
        printf("  总权值 = %d\n", primTotal);
    }

// 重新抽一次边表（上一个算法的排序会打乱它，为了对比干净）
    n = BuildEdgeList(&G, edgeList);

// ==== Kruskal ====
    printf("\n=== Kruskal（加边法）===\n");
    kruskalTotal = Kruskal(&G, edgeList, n);

    if (kruskalTotal < 0)
    {
        printf("  图不连通，没有生成树\n");
    }
    else
    {
        printf("  总权值 = %d\n", kruskalTotal);
    }

// 两个结果必须一致
    printf("\n两种算法结果对比：\n");
    printf("  Prim    = %d\n", primTotal);
    printf("  Kruskal = %d\n", kruskalTotal);

    if (primTotal == kruskalTotal)
    {
        printf("  一致 —— 两种完全不同的思路给出同一个总权值，说明都对\n");
    }
    else
    {
        printf("  不一致！至少有一个写错了\n");
    }

    printf("\n（Prim 和 Dijkstra 只差一行：\n");
    printf("  Dijkstra 是 dist[v] + g[v][w]，Prim 是 g[v][w]）\n");

// 正常结束
    return 0;
}

